// graphify-viewer.js — serves the Graphify codebase knowledge graph viewer.
// Reads graphify-out/graph.html from the AHD repo and wraps it in an iframe
// inside the ops dashboard shell so it fits the existing nav/layout.
//
// graph.html is a self-contained interactive force-directed graph (no external
// deps) generated by "graphify .". It's 44MB with 34K nodes inline — too heavy
// for mobile. We serve a 595KB community-level summary graph (1,411 community
// nodes, 2K inter-community edges) on small screens instead.
//
// Regenerate with:
//   cd /root/projects/a-house-divided && OLLAMA_MODEL=deepseek-v4-flash:cloud graphify extract . --backend ollama --max-concurrency 4
//   cd /root/projects/a-house-divided && GRAPHIFY_VIZ_NODE_LIMIT=50000 graphify cluster-only . --no-label --no-cluster
//   python3 /tmp/build-comm-graph.py  # rebuild community summary graph

const fs = require("fs");
const path = require("path");
const { primaryRepoDir } = require("./src/core/paths");

const GRAPHIFY_OUT = process.env.GRAPHIFY_OUT || (() => {
  const repo = primaryRepoDir();
  return repo ? path.join(repo, "graphify-out") : "";
})();

function readGraphHTML() {
  const p = path.join(GRAPHIFY_OUT, "graph.html");
  if (!fs.existsSync(p)) return null;
  return fs.readFileSync(p, "utf8");
}

function readCommunityHTML() {
  const p = path.join(GRAPHIFY_OUT, "graph-communities.html");
  if (!fs.existsSync(p)) return null;
  return fs.readFileSync(p, "utf8");
}

function getGraphInfo() {
  const p = path.join(GRAPHIFY_OUT, "graph.json");
  if (!fs.existsSync(p)) return null;
  try {
    const g = JSON.parse(fs.readFileSync(p, "utf8"));
    const nodes = g.nodes || (g.elements && g.elements.nodes) || [];
    const edges = g.links || g.edges || (g.elements && g.elements.edges) || [];
    const n = Array.isArray(nodes) ? nodes.length : 0;
    const e = Array.isArray(edges) ? edges.length : 0;
    const mtime = fs.statSync(p).mtime;
    return { nodes: n, edges: e, updatedAt: mtime.toISOString() };
  } catch {
    return null;
  }
}

const EXTRA_CSS = [
  '.gf-wrap{max-width:100%;margin:0 auto;display:flex;flex-direction:column;gap:0}',
  '.gf-head{display:flex;align-items:center;justify-content:space-between;padding:10px var(--s-4,16px);gap:12px;flex-wrap:wrap;border-bottom:1px solid var(--border,#2a2a2a)}',
  '.gf-head h1{font-size:1.1rem;font-weight:700;margin:0;display:flex;align-items:center;gap:8px}',
  '.gf-head .gf-meta{font-size:.78rem;color:var(--text-3,#888);display:flex;gap:14px;flex-wrap:wrap}',
  '.gf-head .gf-meta span{display:inline-flex;align-items:center;gap:4px}',
  '.gf-iframe-wrap{flex:1;position:relative}',
  '.gf-iframe-wrap iframe{width:100%;height:calc(100vh - var(--ops-bar-h, 52px) - 52px);border:0;display:block}',
  '.gf-empty{text-align:center;padding:60px 20px;color:var(--text-3,#888)}',
  '.gf-empty h2{font-size:1.2rem;margin:0 0 8px;color:var(--text-2,#bbb)}',
  '.gf-empty p{font-size:.88rem;max-width:480px;margin:0 auto 16px}',
  '.gf-empty code{background:var(--bg-0,#0e0e0e);padding:.15em .5em;border-radius:4px;font-size:.95em}',
  '.gf-toggle{display:flex;gap:6px;margin-left:auto}',
  '.gf-toggle button{padding:4px 10px;border-radius:6px;border:1px solid var(--border,#2a2a4e);background:var(--glass-2,#1a1a2e);color:var(--text-2,#ccc);font-size:.75rem;cursor:pointer;transition:all .15s}',
  '.gf-toggle button.active{background:var(--accent,#4E79A7);color:#fff;border-color:var(--accent,#4E79A7)}',
  '@media (max-width:640px){',
  '  .gf-head{flex-direction:column;align-items:flex-start}',
  '  .gf-iframe-wrap iframe{height:calc(100vh - var(--ops-bar-h, 52px) - 70px)}',
  '}',
].join('\n');

function makeGraphifyBody() {
  const fullHTML = readGraphHTML();
  const commHTML = readCommunityHTML();
  const info = getGraphInfo();

  if (!fullHTML && !commHTML) {
    return {
      extraCss: EXTRA_CSS,
      body: [
        '<div class="gf-wrap">',
        '  <div class="gf-head">',
        '    <h1>Graphify — Codebase Knowledge Graph</h1>',
        '  </div>',
        '  <div class="gf-empty">',
        '    <h2>No graph generated yet</h2>',
        '    <p>Run <code>OLLAMA_MODEL=deepseek-v4-flash:cloud graphify extract . --backend ollama</code> on the dev machine to generate the interactive codebase graph.</p>',
        '    <p style="font-size:.78rem;margin-top:12px">Or set up a cron job to regenerate automatically.</p>',
        '  </div>',
        '</div>',
      ].join('\n'),
    };
  }

  let infoLine = '';
  if (info) {
    infoLine = '<div class="gf-meta"><span>⬤ ' + info.nodes.toLocaleString() +
      ' nodes</span><span>↔ ' + info.edges.toLocaleString() +
      ' edges</span><span>Updated ' + new Date(info.updatedAt).toLocaleString() + '</span></div>';
  }

  // Mobile: serve community graph (595KB, 1.4K nodes) instead of full (44MB, 34K nodes)
  var isMobile = false;
  // Server-side UA check is unreliable; client-side JS decides which iframe to load.
  // We provide both URLs and let the browser pick based on screen width.

  return {
    extraCss: EXTRA_CSS,
    body: [
      '<div class="gf-wrap">',
      '  <div class="gf-head">',
      '    <h1>Graphify — Codebase Knowledge Graph</h1>',
      '    ' + infoLine,
      '    <div class="gf-toggle">',
      '      <button id="gf-full-btn" onclick="gfSwitch(\'full\')">Full graph (34K nodes)</button>',
      '      <button id="gf-comm-btn" class="active" onclick="gfSwitch(\'comm\')">Communities (1.4K)</button>',
      '    </div>',
      '  </div>',
      '  <div class="gf-iframe-wrap">',
      '    <iframe id="gf-frame" src="/graphify/graph-communities.html" title="Graphify codebase knowledge graph" sandbox="allow-scripts allow-same-origin"></iframe>',
      '  </div>',
      '</div>',
      '<script>',
      '(function(){',
      '  var frame = document.getElementById("gf-frame");',
      '  var fullBtn = document.getElementById("gf-full-btn");',
      '  var commBtn = document.getElementById("gf-comm-btn");',
      '  // Auto-switch to community graph on small screens',
      '  function autoPick(){',
      '    if (screen.width < 768 || window.innerWidth < 768) { gfSwitch("comm"); }',
      '  }',
      '  autoPick();',
      '})()',
      '</script>',
    ].join('\n'),
  };
}

// Client-side toggle script (injected into the shell page)
const GF_SWITCH_JS = `
<script>
function gfSwitch(mode) {
  var frame = document.getElementById('gf-frame');
  var fullBtn = document.getElementById('gf-full-btn');
  var commBtn = document.getElementById('gf-comm-btn');
  if (mode === 'full') {
    frame.src = '/graphify/graph.html';
    fullBtn.classList.add('active');
    commBtn.classList.remove('active');
  } else {
    frame.src = '/graphify/graph-communities.html';
    commBtn.classList.add('active');
    fullBtn.classList.remove('active');
  }
}
</script>
`;

module.exports = { makeGraphifyBody, readGraphHTML, readCommunityHTML, getGraphInfo, GF_SWITCH_JS };